def english_question(question):
    """Return the English prompt and original-order options for a seeded question."""
    difficulty = question.difficulty
    if not isinstance(difficulty, int) or not 1 <= difficulty <= len(ENGLISH_QUESTIONS):
        return None
    return ENGLISH_QUESTIONS[difficulty - 1]
